// Arcadia for Margin.app's overlay to fall back on (scripts/build.js fallbackPackage).
globalThis.marginFallbackTheme = {"id":"arcadia","manifest":"{\n  \"format\": 2,\n  \"id\": \"arcadia\",\n  \"name\": \"Arcadia\",\n  \"version\": \"2.0.0\",\n  \"author\": \"Margin\",\n  \"description\": \"Arc's look: a gray frame around the rounded page card, space chips, pins and tabs, a dark command bar.\",\n  \"modes\": [\"fullscreen\", \"windowed\", \"inpage\"],\n  \"settings\": {\n    \"sidebarWidth\": { \"type\": \"number\", \"default\": 260, \"min\": 160, \"max\": 500, \"step\": 10, \"label\": \"Sidebar width\" }\n  },\n  \"layout\": { \"reveal\": \"left\", \"sidebarMin\": 160, \"sidebarMax\": 500, \"sidebarDefault\": 260 }\n}\n","html":"<div class=\"arcadia\" m-attr:data-mode=\"{{window.mode}}\" m-attr:data-sidebar=\"{{window.sidebar}}\" m-class:framed=\"{{window.frameWhenHidden}}\" m-class:loading=\"{{tab.loading}}\" m-class:newtab=\"{{launcher}}\" m-class:switching=\"{{switchCover}}\" m-style:--space-color=\"{{space.color}}\">\n\n  <!-- Rows carry their ids as data-* (for the tests that drive the sidebar).\n       The page card: the browser's page goes in its box (Margin's <m-page>).\n       Its huge spread shadow is the gray frame around it (Arc's), so the\n       card itself stays clear. -->\n  <m-page class=\"page\"></m-page>\n\n  <!-- A switch to another profile getting ready (Margin.app): the page card\n       covered, saying where it goes. Under the sidebar, so a sidebar out over\n       the page stays usable; the launcher steps aside for it. -->\n  <m-switch-cover class=\"switch-cover-slot\"></m-switch-cover>\n\n  <!-- The hover zone at the left edge that brings a hidden sidebar out (m-peek). -->\n  <div class=\"peek-zone\" m-peek=\"left\" aria-hidden=\"true\"></div>\n\n  <aside class=\"margin-sidebar\" aria-label=\"Margin\" m-swipe=\"spaces\">\n    <header class=\"top\">\n      <m-window-controls class=\"window-controls\"></m-window-controls>\n      <m-if test=\"window.pinnedOpen\">\n        <button class=\"keep-open\" title=\"Auto-hide the sidebar\" aria-label=\"Auto-hide the sidebar\" aria-pressed=\"true\" m-action=\"sidebar.toggle\">\n          <svg class=\"line-icon toggle-icon\" viewBox=\"0 0 19 15\" aria-hidden=\"true\"><rect x=\"0.75\" y=\"0.75\" width=\"17.5\" height=\"13.5\" rx=\"3\"></rect><path d=\"M6.25 0.75v13.5M2.75 4h1.5M2.75 6.5h1.5M2.75 9h1.5\"></path></svg>\n        </button>\n        <m-else>\n          <button class=\"keep-open\" title=\"Keep the sidebar open\" aria-label=\"Keep the sidebar open\" aria-pressed=\"false\" m-action=\"sidebar.toggle\">\n            <svg class=\"line-icon toggle-icon\" viewBox=\"0 0 19 15\" aria-hidden=\"true\"><rect x=\"0.75\" y=\"0.75\" width=\"17.5\" height=\"13.5\" rx=\"3\"></rect><path d=\"M6.25 0.75v13.5M2.75 4h1.5M2.75 6.5h1.5M2.75 9h1.5\"></path></svg>\n          </button>\n        </m-else>\n      </m-if>\n      <m-drag-region class=\"spacer\"></m-drag-region>\n      <button class=\"bar-button address\" title=\"{{tab.url}}\" aria-label=\"Search or enter address\" m-action=\"palette.open\">\n        <svg class=\"line-icon search-icon\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M10.5 3.3a7.2 7.2 0 1 0 0 14.4 7.2 7.2 0 0 0 0-14.4Z\"></path><path d=\"M15.6 15.6 19.5 19.5\"></path></svg>\n      </button>\n    </header>\n\n    <!-- The space's part (its name, the editor, the list): what a sideways swipe moves. -->\n    <div class=\"space-pane\">\n      <div class=\"space-title\">\n        <span class=\"emoji\" aria-hidden=\"true\">{{space.emoji}}</span>\n        <span class=\"title\" m-rename=\"space\">{{space.name}}</span>\n      </div>\n\n      <m-editor class=\"editor-slot\"></m-editor>\n\n      <section class=\"tabs-section\" m-scroll=\"tabs\">\n        <div class=\"pins-section\">\n          <div class=\"pins\" role=\"list\" aria-label=\"Pinned\" m-class:has=\"{{space.hasPinned}}\" m-drop=\"pins\">\n            <m-for each=\"space.pinned\" as=\"g\">\n              <m-if test=\"g.isFolder\">\n                <a class=\"folder\" role=\"button\" tabindex=\"0\" data-folder-id=\"{{g.id}}\" m-class:open=\"{{g.open}}\" m-attr:aria-expanded=\"{{g.open}}\" m-action=\"folder.toggle\" m-arg=\"{{g.id}}\" m-drag=\"folder\" m-drop=\"folder\">\n                  <span class=\"folder-toggle\">\n                    <m-if test=\"g.open\">\n                      <svg class=\"folder-icon open\" viewBox=\"0 0 22.5 16.5\" aria-hidden=\"true\"><path class=\"folder-back\" d=\"M5.2 15.9Q4.4 15.9 4.2 15.1L.75 2.2Q.4.6 2 .6H5.6Q6.3.6 6.8 1.1L8.2 2.6Q8.6 3 9.2 3.05L20.6 4.1Q21.6 4.2 21.4 5.2L17.9 15.9Z\"></path><path class=\"folder-front\" d=\"M8.7 5.2H21.1Q22 5.2 21.7 6.1L18.6 15.3Q18.4 15.9 17.7 15.9H5Q4.15 15.9 4.4 15.1L7.4 6.3Q7.75 5.2 8.7 5.2Z\"></path></svg>\n                      <m-else>\n                        <svg class=\"folder-icon\" viewBox=\"0 0 22.5 16.5\" aria-hidden=\"true\"><path class=\"folder-back\" d=\"M1 2.1Q1 .6 2.5 .6H6.6Q7.2.6 7.6 1.1L8.9 2.6H20Q21.5 2.6 21.5 4.1V14.4Q21.5 15.9 20 15.9H2.5Q1 15.9 1 14.4Z\"></path><path class=\"folder-front\" d=\"M1 6.3Q1 4.8 2.5 4.8H20Q21.5 4.8 21.5 6.3V14.4Q21.5 15.9 20 15.9H2.5Q1 15.9 1 14.4Z\"></path></svg>\n                      </m-else>\n                    </m-if>\n                    <span class=\"title\" m-rename=\"folder\">{{g.name}}</span>\n                  </span>\n                </a>\n                <m-for each=\"g.shown\" as=\"p\">\n                  <a class=\"pin nested\" data-pin-id=\"{{p.id}}\" m-class:active=\"{{p.active}}\" m-class:behind=\"{{p.behind}}\" m-class:open=\"{{p.open}}\" m-class:asleep=\"{{p.asleep}}\" m-class:busy=\"{{p.loading}}\" aria-label=\"{{p.title}}\" m-action=\"pin.open\" m-arg=\"{{p.id}}\" m-drag=\"pin\">\n                      <m-if test=\"p.icon\">\n                        <img class=\"avatar\" alt=\"\" m-icon=\"{{p.icon}}\">\n                        <m-else><span class=\"avatar letter\" aria-hidden=\"true\" m-style:--letter=\"{{p.color}}\">{{p.letter}}</span></m-else>\n                      </m-if>\n                      <span class=\"title\">{{p.title}}</span>\n                    <m-if test=\"p.audible\">\n                      <svg class=\"audible-icon\" viewBox=\"0 0 16 16\" aria-label=\"Playing audio\"><path class=\"speaker\" d=\"M2.5 6h2l3-2.5v9L4.5 10h-2Z\"></path><path d=\"M10 5.5a3.5 3.5 0 0 1 0 5M11.8 3.7a6 6 0 0 1 0 8.6\"></path></svg>\n                    </m-if>\n                    <m-if test=\"p.open\">\n                      <button class=\"icon close\" aria-label=\"Close tab (stays pinned)\" m-action=\"tab.close\" m-arg=\"{{p.tabId}}\">\n                        <svg class=\"line-icon close-icon\" viewBox=\"0 0 11 11\" aria-hidden=\"true\"><path d=\"M1 1l9 9M10 1l-9 9\"></path></svg>\n                      </button>\n                    </m-if>\n                  </a>\n                </m-for>\n                <m-else>\n                  <a class=\"pin\" data-pin-id=\"{{g.id}}\" m-class:active=\"{{g.active}}\" m-class:behind=\"{{g.behind}}\" m-class:open=\"{{g.open}}\" m-class:asleep=\"{{g.asleep}}\" m-class:busy=\"{{g.loading}}\" aria-label=\"{{g.title}}\" m-action=\"pin.open\" m-arg=\"{{g.id}}\" m-drag=\"pin\">\n                      <m-if test=\"g.icon\">\n                        <img class=\"avatar\" alt=\"\" m-icon=\"{{g.icon}}\">\n                        <m-else><span class=\"avatar letter\" aria-hidden=\"true\" m-style:--letter=\"{{g.color}}\">{{g.letter}}</span></m-else>\n                      </m-if>\n                      <span class=\"title\">{{g.title}}</span>\n                    <m-if test=\"g.audible\">\n                      <svg class=\"audible-icon\" viewBox=\"0 0 16 16\" aria-label=\"Playing audio\"><path class=\"speaker\" d=\"M2.5 6h2l3-2.5v9L4.5 10h-2Z\"></path><path d=\"M10 5.5a3.5 3.5 0 0 1 0 5M11.8 3.7a6 6 0 0 1 0 8.6\"></path></svg>\n                    </m-if>\n                    <m-if test=\"g.open\">\n                      <button class=\"icon close\" aria-label=\"Close tab (stays pinned)\" m-action=\"tab.close\" m-arg=\"{{g.tabId}}\">\n                        <svg class=\"line-icon close-icon\" viewBox=\"0 0 11 11\" aria-hidden=\"true\"><path d=\"M1 1l9 9M10 1l-9 9\"></path></svg>\n                      </button>\n                    </m-if>\n                  </a>\n                </m-else>\n              </m-if>\n            </m-for>\n            <div class=\"drop-hint\" aria-hidden=\"true\">Drop to pin</div>\n          </div>\n        </div>\n        <m-if test=\"space.hasPinned\">\n          <div class=\"divider\"></div>\n        </m-if>\n\n        <!-- iCloud Tabs (Margin.app with Safari): a live folder above \"+ New Tab\", outside every drop zone. -->\n        <m-cloud-tabs class=\"cloud-slot\"></m-cloud-tabs>\n\n        <div class=\"tabs\" role=\"list\" aria-label=\"Tabs\" m-drop=\"tabs\">\n          <a class=\"new-tab-row\" role=\"button\" aria-label=\"New Tab\" m-class:active=\"{{space.newTab.active}}\" m-attr:aria-current=\"{{space.newTab.active}}\" m-action=\"tab.new\">\n            <span class=\"plus\" aria-hidden=\"true\"><svg class=\"line-icon plus-icon\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M7 1v12M1 7h12\"></path></svg></span>\n            <span class=\"title\">New Tab</span>\n          </a>\n          <m-for each=\"space.today\" as=\"t\">\n            <a class=\"tab\" data-tab-id=\"{{t.id}}\" m-class:active=\"{{t.active}}\" m-class:behind=\"{{t.behind}}\" m-class:asleep=\"{{t.asleep}}\" m-class:busy=\"{{t.loading}}\" m-class:not-open=\"{{t.notOpen}}\" aria-label=\"{{t.title}}\" m-action=\"tab.activate\" m-arg=\"{{t.id}}\" m-drag=\"tab\">\n                <m-if test=\"t.icon\">\n                  <img class=\"avatar\" alt=\"\" m-icon=\"{{t.icon}}\">\n                  <m-else><span class=\"avatar letter\" aria-hidden=\"true\" m-style:--letter=\"{{t.color}}\">{{t.letter}}</span></m-else>\n                </m-if>\n                <span class=\"title\">{{t.title}}</span>\n              <m-if test=\"t.audible\">\n                <svg class=\"audible-icon\" viewBox=\"0 0 16 16\" aria-label=\"Playing audio\"><path class=\"speaker\" d=\"M2.5 6h2l3-2.5v9L4.5 10h-2Z\"></path><path d=\"M10 5.5a3.5 3.5 0 0 1 0 5M11.8 3.7a6 6 0 0 1 0 8.6\"></path></svg>\n              </m-if>\n              <button class=\"icon close\" aria-label=\"Close tab\" m-action=\"tab.close\" m-arg=\"{{t.id}}\">\n                <svg class=\"line-icon close-icon\" viewBox=\"0 0 11 11\" aria-hidden=\"true\"><path d=\"M1 1l9 9M10 1l-9 9\"></path></svg>\n              </button>\n            </a>\n          </m-for>\n        </div>\n      </section>\n    </div>\n\n    <!-- The bottom bar (Arc): archive at the left, the spaces in the middle, \"+\" at the right. -->\n    <footer class=\"bar\">\n      <button class=\"bar-button archive\" title=\"Archived tabs\" aria-label=\"Archived tabs\" m-action=\"archive.open\">\n        <svg class=\"fill-icon archive-icon\" viewBox=\"0 0 14 16.5\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M2 7.5H13Q13.5 7.5 13.5 8V13.5Q13.5 16.5 10.5 16.5H4.5Q1.5 16.5 1.5 13.5V8Q1.5 7.5 2 7.5ZM6.5 8.5H8.5A1 1 0 0 1 8.5 10.5H6.5A1 1 0 0 1 6.5 8.5Z\"></path><path d=\"M.9 6.1Q.4 6 .2 5.3L0 4.7Q0 4 .7 3.9L2.8 3.6L4 1.4Q4.35.85 4.75 1.4L5.95 3.1L8.6 3.2Q9.25 3.25 9.05 3.85L8.4 5.7Q8.25 6.1 7.8 6.1Z\"></path><path d=\"M11.4 2.9Q11.8 2.3 12.2 2.9L14 5.2Q14.3 5.7 13.8 5.9L11.3 6.4Q10.6 6.5 10.6 5.8Z\"></path><circle cx=\"9.5\" cy=\"1\" r=\"1\"></circle></svg>\n      </button>\n      <nav class=\"spaces\" aria-label=\"Spaces\">\n        <m-for each=\"spaces\" as=\"s\">\n          <!-- Several browser profiles (Margin.app): a thin divider where one profile's spaces give way to another's, and another profile's spaces carry its mark. -->\n          <m-if test=\"s.profileStart\"><span class=\"profile-divider\" aria-hidden=\"true\"></span></m-if>\n          <button class=\"chip\" data-space-id=\"{{s.id}}\" m-class:active=\"{{s.active}}\" m-class:foreign=\"{{s.foreign}}\" m-class:switching=\"{{s.switching}}\" title=\"{{s.label}}\" m-attr:aria-label=\"{{s.label}}\" m-attr:aria-pressed=\"{{s.active}}\" m-style:--chip-color=\"{{s.color}}\" m-action=\"space.switch\" m-arg=\"{{s.id}}\" m-drop=\"space\">{{s.emoji}}<m-if test=\"s.profileMark\"><span class=\"profile-mark\" m-style:--profile-color=\"{{s.profile.color}}\" aria-hidden=\"true\"><m-if test=\"s.profile.symbol\"><img class=\"profile-symbol\" alt=\"\" m-icon=\"{{s.profile.symbol}}\"><m-else>{{s.profile.initial}}</m-else></m-if></span></m-if></button>\n        </m-for>\n      </nav>\n      <button class=\"bar-button add\" title=\"New folder or space\" aria-label=\"New folder or space\" m-action=\"menu.open\" m-arg=\"add\">\n        <svg class=\"line-icon plus-icon\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M7 1v12M1 7h12\"></path></svg>\n      </button>\n    </footer>\n\n    <!-- Resize handle: the sidebar's right edge (160–500 px, the sidebarWidth setting). -->\n    <div class=\"resizer\" m-resize=\"sidebar\" title=\"Drag to resize · double-click to reset\" aria-hidden=\"true\"></div>\n  </aside>\n\n  <!-- The card's soft shadow, above the sidebar so it also falls on its edge,\n       and the page-load pill in the frame's top strip. -->\n  <div class=\"card-edge\" aria-hidden=\"true\">\n    <div class=\"loader\"><div class=\"loader-bar\"></div></div>\n    <!-- Margin's trackpad gestures on the page (pull to refresh at the top,\n         swipe back and forward at the sides): a dark round badge that comes\n         in with the fingers and takes the space's color once letting go\n         would do it. Never takes the pointer. -->\n    <m-if test=\"gesture.pull\">\n      <div class=\"gesture pull\" m-class:armed=\"{{gesture.armed}}\" m-class:done=\"{{gesture.done}}\" m-style:--gesture=\"{{gesture.progress}}\">\n        <svg class=\"line-icon\" viewBox=\"0 0 24 24\"><path d=\"M19.5 12a7.5 7.5 0 1 1-2.2-5.3M19.5 4.5v4h-4\"></path></svg>\n      </div>\n    </m-if>\n    <m-if test=\"gesture.swipe\">\n      <div class=\"gesture swipe\" m-class:back=\"{{gesture.back}}\" m-class:forward=\"{{gesture.forward}}\" m-class:armed=\"{{gesture.armed}}\" m-class:done=\"{{gesture.done}}\" m-style:--gesture=\"{{gesture.progress}}\">\n        <svg class=\"line-icon\" viewBox=\"0 0 24 24\"><path d=\"M15 5l-7 7 7 7\"></path></svg>\n      </div>\n    </m-if>\n  </div>\n\n  <!-- The new-tab page's launcher, in the page card (while the UI is drawn in Margin's new-tab page). -->\n  <m-launcher class=\"launcher-slot\"></m-launcher>\n\n  <!-- Arc's command bar. -->\n  <m-if test=\"palette.open\">\n    <div class=\"palette-layer\">\n      <button class=\"backdrop\" aria-label=\"Close the command bar\" m-action=\"palette.close\"></button>\n      <div class=\"palette\" role=\"dialog\" aria-label=\"Margin command palette\">\n        <div class=\"search\">\n          <svg class=\"search-icon\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M10.5 3.3a7.2 7.2 0 1 0 0 14.4 7.2 7.2 0 0 0 0-14.4Z\"></path><path d=\"M15.6 15.6 19.5 19.5\"></path></svg>\n          <input class=\"query\" type=\"text\" m-input=\"palette\" placeholder=\"Search or Enter URL…\" aria-label=\"Command palette\" spellcheck=\"false\" autocomplete=\"off\" role=\"combobox\" aria-expanded=\"true\" aria-controls=\"margin-results\">\n        </div>\n        <div class=\"results\" id=\"margin-results\" role=\"listbox\">\n          <m-for each=\"palette.rows\" as=\"r\">\n            <!-- A run of rows from one place (iCloud Tabs: \"On Tirth's iPhone\"): its heading. -->\n            <m-if test=\"r.sectionStart\"><div class=\"result-section\" aria-hidden=\"true\">{{r.section}}</div></m-if>\n            <a class=\"result\" role=\"option\" data-id=\"{{r.id}}\" title=\"{{r.title}}\" m-attr:aria-selected=\"{{r.selected}}\" m-attr:aria-description=\"{{r.section}}\" m-action=\"palette.run\" m-arg=\"{{r.id}}\">\n                <m-if test=\"r.emoji\">\n                  <span class=\"avatar emoji\">{{r.emoji}}</span>\n                  <m-else>\n                    <m-if test=\"r.icon\">\n                      <img class=\"avatar\" alt=\"\" m-icon=\"{{r.icon}}\">\n                      <m-else><span class=\"avatar letter\" aria-hidden=\"true\" m-style:--letter=\"{{r.color}}\">{{r.letter}}</span></m-else>\n                    </m-if>\n                  </m-else>\n                </m-if>\n                <span class=\"title\">{{r.title}}</span>\n                <m-if test=\"r.badge\"><span class=\"badge\">{{r.badge}}</span></m-if>\n                <m-if test=\"r.goes\">\n                  <span class=\"go-button\"><svg class=\"arrow-icon\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4.5 12h14.5\"></path><path d=\"M12 4.5l7.5 7.5-7.5 7.5\"></path></svg></span>\n                </m-if>\n            </a>\n          </m-for>\n          <m-if test=\"!palette.hasRows\">\n            <div class=\"result empty\">No matches</div>\n          </m-if>\n        </div>\n      </div>\n    </div>\n  </m-if>\n\n  <m-menu class=\"menu-slot\"></m-menu>\n  <m-notice class=\"notice-slot\"></m-notice>\n  <m-prompt class=\"prompt-slot\"></m-prompt>\n\n  <!-- Right-click menus on tabs, pins, folders and spaces, and \"+\" (macOS-style). -->\n  <!-- iCloud Tabs: the tabs open on the person's other devices, as a folder\n       that's clearly live: a cloud in Arc's folder place, no dragging in or\n       out, each device's tabs under its icon, name and when it was last used.\n       Every word is Margin's (a guarded part). -->\n  <template m-part=\"cloud-tabs\">\n    <div class=\"cloud\" role=\"group\" m-attr:aria-label=\"{{cloudTabs.labels.title}}\" m-class:open=\"{{cloudTabs.open}}\">\n      <a class=\"folder cloud-head\" role=\"button\" tabindex=\"0\" title=\"{{cloudTabs.labels.toggle}}\" m-class:open=\"{{cloudTabs.open}}\" m-attr:aria-expanded=\"{{cloudTabs.open}}\" m-action=\"cloud.toggle\">\n        <span class=\"folder-toggle\">\n          <svg class=\"cloud-icon\" viewBox=\"0 0 22.5 16.5\" aria-hidden=\"true\"><path class=\"cloud-back\" d=\"M6.2 15.6H17.4A4.4 4.4 0 0 0 18 6.85 6.2 6.2 0 0 0 6.25 5.3 5.15 5.15 0 0 0 6.2 15.6Z\"></path><path class=\"cloud-shine\" d=\"M8.4 7.4a3.6 3.6 0 0 1 4.6-1.3\"></path></svg>\n          <span class=\"title\">{{cloudTabs.labels.title}}</span>\n        </span>\n        <m-if test=\"cloudTabs.hasCount\"><span class=\"cloud-count\">{{cloudTabs.count}}</span></m-if>\n        <svg class=\"cloud-chevron\" viewBox=\"0 0 10 10\" aria-hidden=\"true\"><path d=\"M3.5 2l3 3-3 3\"></path></svg>\n      </a>\n      <m-if test=\"cloudTabs.open\">\n        <m-if test=\"cloudTabs.hasMessage\">\n          <div class=\"cloud-note\" role=\"status\">\n            <span class=\"text\">{{cloudTabs.message}}</span>\n            <m-if test=\"cloudTabs.canFix\"><button class=\"cloud-fix\" m-action=\"cloud.access\">{{cloudTabs.labels.fix}}</button></m-if>\n          </div>\n        </m-if>\n        <m-for each=\"cloudTabs.devices\" as=\"d\">\n          <a class=\"cloud-device\" role=\"button\" tabindex=\"0\" data-device-id=\"{{d.id}}\" title=\"{{d.describe}}\" m-class:open=\"{{d.open}}\" m-class:stale=\"{{d.stale}}\" m-attr:aria-expanded=\"{{d.open}}\" m-attr:aria-label=\"{{d.describe}}\" m-action=\"cloud.toggleDevice\" m-arg=\"{{d.id}}\">\n            <span class=\"device-icon\" aria-hidden=\"true\">\n              <m-if test=\"d.isPhone\"><svg viewBox=\"0 0 16 16\"><rect x=\"4.25\" y=\"1.25\" width=\"7.5\" height=\"13.5\" rx=\"2\"></rect><path d=\"M7 12.4h2\"></path></svg></m-if>\n              <m-if test=\"d.isPad\"><svg viewBox=\"0 0 16 16\"><rect x=\"2.25\" y=\"1.25\" width=\"11.5\" height=\"13.5\" rx=\"1.75\"></rect><path d=\"M7 12.4h2\"></path></svg></m-if>\n              <m-if test=\"d.isMac\"><svg viewBox=\"0 0 16 16\"><rect x=\"2.75\" y=\"3\" width=\"10.5\" height=\"7.5\" rx=\"1.25\"></rect><path d=\"M1 12.75h14\"></path></svg></m-if>\n              <m-if test=\"d.isVision\"><svg viewBox=\"0 0 16 16\"><path d=\"M1.5 7.2c0-1.9 1.3-2.95 3.4-2.95h6.2c2.1 0 3.4 1.05 3.4 2.95 0 2.05-1.25 3.55-3.05 3.55-1.4 0-1.95-1.15-3.45-1.15S6 10.75 4.55 10.75C2.75 10.75 1.5 9.25 1.5 7.2Z\"></path></svg></m-if>\n              <m-if test=\"d.isOther\"><svg viewBox=\"0 0 16 16\"><circle cx=\"8\" cy=\"8\" r=\"6.25\"></circle><path d=\"M1.75 8h12.5M8 1.75c-3.3 3.6-3.3 8.9 0 12.5M8 1.75c3.3 3.6 3.3 8.9 0 12.5\"></path></svg></m-if>\n            </span>\n            <span class=\"device-name\">{{d.name}}</span>\n            <span class=\"device-when\">{{d.updated}}</span>\n          </a>\n          <m-for each=\"d.shown\" as=\"t\">\n            <a class=\"cloud-tab\" role=\"link\" data-cloud-tab-id=\"{{t.id}}\" title=\"{{t.url}}\" m-class:stale=\"{{d.stale}}\" m-attr:aria-label=\"{{t.label}}\" m-action=\"cloud.open\" m-arg=\"{{t.id}}\">\n              <m-if test=\"t.icon\">\n                <img class=\"avatar\" alt=\"\" m-icon=\"{{t.icon}}\">\n                <m-else><span class=\"avatar letter\" aria-hidden=\"true\" m-style:--letter=\"{{t.color}}\">{{t.letter}}</span></m-else>\n              </m-if>\n              <span class=\"cloud-text\">\n                <span class=\"title\">{{t.title}}</span>\n                <span class=\"cloud-host\">{{t.host}}</span>\n              </span>\n              <m-if test=\"t.pinned\">\n                <span class=\"pinned-mark\" title=\"{{cloudTabs.labels.pinned}}\"><svg viewBox=\"0 0 12 12\" aria-hidden=\"true\"><path d=\"M4.4 1.5h3.2l-.4 3.1 1.6 1.6v.9H3.2v-.9l1.6-1.6ZM6 7.1v3.4\"></path></svg></span>\n              </m-if>\n            </a>\n          </m-for>\n        </m-for>\n      </m-if>\n      <div class=\"divider cloud-divider\"></div>\n    </div>\n  </template>\n\n  <template m-part=\"menu\">\n    <div class=\"tab-menu\" role=\"menu\" m-attr:aria-label=\"{{menu.label}}\">\n      <m-for each=\"menu.items\" as=\"i\">\n        <m-if test=\"i.separator\">\n          <div class=\"menu-separator\" role=\"separator\"></div>\n          <m-else>\n            <button class=\"menu-item\" role=\"menuitem\" m-class:danger=\"{{i.danger}}\" m-class:confirming=\"{{i.confirming}}\" m-action=\"menu.run\" m-arg=\"{{i.id}}\">{{i.label}}</button>\n          </m-else>\n        </m-if>\n      </m-for>\n    </div>\n  </template>\n\n  <!-- The space editor, under the space's name. -->\n  <template m-part=\"space-editor\">\n    <div class=\"editor\" role=\"form\" m-attr:aria-label=\"{{editor.labels.title}}\">\n      <div class=\"row\">\n        <input class=\"emoji\" type=\"text\" m-input=\"space-emoji\" maxlength=\"8\" m-attr:aria-label=\"{{editor.labels.emoji}}\" autocomplete=\"off\" spellcheck=\"false\">\n        <input class=\"name\" type=\"text\" m-input=\"space-name\" maxlength=\"40\" m-attr:placeholder=\"{{editor.labels.name}}\" m-attr:aria-label=\"{{editor.labels.name}}\" m-attr:disabled=\"{{editor.nameLocked}}\" autocomplete=\"off\" spellcheck=\"false\">\n      </div>\n      <m-if test=\"editor.nameLocked\"><div class=\"note\">{{editor.labels.note}}</div></m-if>\n      <div class=\"swatches\" role=\"radiogroup\" m-attr:aria-label=\"{{editor.labels.colors}}\">\n        <m-for each=\"editor.colors\" as=\"c\">\n          <button class=\"swatch\" role=\"radio\" title=\"{{c.color}}\" m-attr:aria-checked=\"{{c.selected}}\" m-style:--chip-color=\"{{c.color}}\" m-action=\"editor.color\" m-arg=\"{{c.id}}\"></button>\n        </m-for>\n      </div>\n      <div class=\"row actions\">\n        <button class=\"delete\" title=\"{{editor.deleteTitle}}\" m-attr:disabled=\"{{editor.cannotDelete}}\" m-class:confirming=\"{{editor.confirmDelete}}\" m-action=\"editor.delete\">{{editor.deleteLabel}}</button>\n        <span class=\"spacer\"></span>\n        <button m-action=\"editor.cancel\">{{editor.labels.cancel}}</button>\n        <button class=\"primary\" m-action=\"editor.save\">{{editor.labels.save}}</button>\n      </div>\n    </div>\n  </template>\n\n  <!-- A notice near the left edge (e.g. \"Margin works in full screen\"), with its buttons. -->\n  <template m-part=\"notice\">\n    <div class=\"notice\" role=\"status\">\n      <span class=\"text\">{{notice.text}}</span>\n      <m-for each=\"notice.actions\" as=\"a\">\n        <button m-class:primary=\"{{a.primary}}\" m-action=\"notice.run\" m-arg=\"{{a.id}}\">{{a.label}}</button>\n      </m-for>\n    </div>\n  </template>\n\n  <!-- Margin's prompts and confirmations (e.g. \"install Margin.app\"). -->\n  <template m-part=\"prompt\">\n    <div class=\"prompt-layer\">\n      <div class=\"prompt\" role=\"alertdialog\" m-attr:aria-label=\"{{prompt.title}}\">\n        <div class=\"prompt-title\">{{prompt.title}}</div>\n        <div class=\"prompt-text\">{{prompt.text}}</div>\n        <div class=\"prompt-actions\">\n          <m-for each=\"prompt.actions\" as=\"a\">\n            <button m-class:primary=\"{{a.primary}}\" m-class:danger=\"{{a.danger}}\" m-action=\"prompt.run\" m-arg=\"{{a.id}}\">{{a.label}}</button>\n          </m-for>\n        </div>\n      </div>\n    </div>\n  </template>\n\n  <!-- The switching cover: the frame's gray, lighter, with the profile's mark,\n       \"Switching to Work…\" and the space under it. No fade. -->\n  <template m-part=\"switch-cover\">\n    <div class=\"switch-cover\" role=\"status\" m-attr:aria-label=\"{{switchCover.label}}\">\n      <div class=\"switch-cover-card\">\n        <m-if test=\"switchCover.profile.emoji\">\n          <span class=\"switch-cover-mark emoji\" aria-hidden=\"true\">{{switchCover.profile.emoji}}</span>\n          <m-else><span class=\"switch-cover-mark\" aria-hidden=\"true\" m-style:--profile=\"{{switchCover.profile.color}}\">{{switchCover.profile.initial}}</span></m-else>\n        </m-if>\n        <span class=\"switch-cover-text\">{{switchCover.text}}</span>\n        <m-if test=\"switchCover.hasSpace\"><span class=\"switch-cover-space\">{{switchCover.space.emoji}} {{switchCover.space.name}}</span></m-if>\n      </div>\n    </div>\n  </template>\n\n  <!-- The new-tab launcher (Arcadia's newtab.html): the search field, the\n       space's pins as tiles, recently archived tabs, and Settings. -->\n  <template m-part=\"launcher\">\n    <main class=\"launcher\">\n      <div class=\"search-field\">\n        <input class=\"launcher-query\" type=\"text\" m-input=\"launcher\" placeholder=\"Search or enter address\" aria-label=\"Search or enter address\" spellcheck=\"false\" autocomplete=\"off\">\n      </div>\n      <m-if test=\"launcher.hasPins\">\n        <section class=\"pins-tiles\">\n          <h2>Pinned</h2>\n          <ul class=\"pin-tiles\">\n            <m-for each=\"launcher.pins\" as=\"p\">\n              <li class=\"tile-item\">\n                <a class=\"tile\" title=\"{{p.url}}\" m-action=\"pin.open\" m-arg=\"{{p.id}}\">\n                  <m-if test=\"p.icon\">\n                    <img class=\"avatar\" alt=\"\" m-icon=\"{{p.icon}}\">\n                    <m-else><span class=\"avatar letter\" aria-hidden=\"true\" m-style:--letter=\"{{p.color}}\">{{p.letter}}</span></m-else>\n                  </m-if>\n                  <span class=\"title\">{{p.title}}</span>\n              </li>\n            </m-for>\n          </ul>\n        </section>\n      </m-if>\n      <m-if test=\"launcher.hasArchive\">\n        <section class=\"archive-section\">\n          <h2>Recently archived</h2>\n          <ul class=\"archive-list\">\n            <m-for each=\"launcher.archive\" as=\"a\">\n              <li class=\"archive-item\">\n                <a class=\"archive-row\" title=\"{{a.url}}\" m-action=\"archive.restore\" m-arg=\"{{a.id}}\">\n                  <m-if test=\"a.icon\">\n                    <img class=\"avatar\" alt=\"\" m-icon=\"{{a.icon}}\">\n                    <m-else><span class=\"avatar letter\" aria-hidden=\"true\" m-style:--letter=\"{{a.color}}\">{{a.letter}}</span></m-else>\n                  </m-if>\n                  <span class=\"title\">{{a.title}}</span>\n                  <span class=\"when\">{{a.ago}}</span>\n                </a>\n              </li>\n            </m-for>\n          </ul>\n          <m-if test=\"launcher.more\">\n            <button class=\"archive-more\" m-action=\"launcher.more\">{{launcher.moreLabel}}</button>\n          </m-if>\n        </section>\n      </m-if>\n      <section class=\"settings\" m-class:open=\"{{launcher.settingsOpen}}\">\n        <div class=\"settings-summary\"><button m-attr:aria-expanded=\"{{launcher.settingsOpen}}\" m-action=\"settings.open\">Settings</button></div>\n        <m-settings class=\"settings-slot\"></m-settings>\n      </section>\n    </main>\n  </template>\n\n  <!-- Settings (Margin's form: its fields, words and inputs are Margin's; this lays them out). -->\n  <template m-part=\"settings\">\n    <div class=\"settings-form\">\n      <m-for each=\"settingsForm.fields\" as=\"f\">\n        <m-if test=\"f.isGroup\">\n          <div class=\"setting-group\" role=\"heading\" aria-level=\"3\">{{f.label}}</div>\n        </m-if>\n        <m-if test=\"f.isInfo\">\n          <p class=\"help\">{{f.label}}</p>\n        </m-if>\n        <m-if test=\"f.isNumber\">\n          <label class=\"setting\"><span class=\"label\">{{f.label}}</span><input class=\"number\" m-input=\"setting-number\"></label>\n        </m-if>\n        <m-if test=\"f.isToggle\">\n          <label class=\"setting\" m-class:disabled=\"{{f.disabled}}\"><span class=\"label\">{{f.label}}</span><input class=\"toggle\" m-input=\"setting-toggle\"></label>\n        </m-if>\n        <m-if test=\"f.isChoice\">\n          <label class=\"setting\"><span class=\"label\">{{f.label}}</span><select class=\"choice\" m-input=\"setting-choice\"></select></label>\n          <m-if test=\"f.hasStatus\"><p class=\"help\" role=\"status\" m-class:error=\"{{f.error}}\">{{f.status}}</p></m-if>\n        </m-if>\n        <m-if test=\"f.isList\">\n          <label class=\"setting stacked\"><span class=\"label\">{{f.label}}</span><textarea class=\"list\" m-input=\"setting-list\" rows=\"3\" spellcheck=\"false\" autocomplete=\"off\"></textarea></label>\n        </m-if>\n        <m-if test=\"f.isColor\">\n          <label class=\"setting\" m-class:theme-own=\"{{f.fromTheme}}\"><span class=\"label\">{{f.label}}</span><input class=\"color\" m-input=\"setting-color\"></label>\n        </m-if>\n        <m-if test=\"f.isShortcut\">\n          <label class=\"setting\"><span class=\"label\">{{f.label}}</span><input class=\"shortcut\" m-input=\"setting-shortcut\" m-class:recording=\"{{f.recording}}\"></label>\n        </m-if>\n        <m-if test=\"f.isButton\">\n          <div class=\"actions\">\n            <button m-action=\"settings.run\" m-arg=\"{{f.id}}\">{{f.label}}</button>\n            <m-if test=\"f.hasStatus\"><span class=\"help\" role=\"status\" m-class:error=\"{{f.error}}\">{{f.status}}</span></m-if>\n          </div>\n        </m-if>\n      </m-for>\n    </div>\n  </template>\n</div>\n","css":"/* Arcadia, Margin's default theme, as a theme package: Arc's look, ported\n   from themes/arcadia (sidebar.css, palette.css, newtab.css, chrome.js) so\n   nothing looks different. A gray frame around the page card (the card is\n   Margin's <m-page>: its box is where the page goes), the sidebar of space\n   chips, pins and tabs at the left, docked (Keep open), hidden (the frame\n   alone, or nothing) or out over the page (peek); a dark command bar;\n   macOS-style menus. Sizes measured from Arc (DECISIONS.md). */\n\n.arcadia {\n  /* One sidebar and frame color (Arc-like neutral gray), the same in Light\n     and Dark Mode; not tinted by the space or taken from the page. */\n  --frame: #9c9da1;\n  /* The sidebar's width: the sidebarWidth setting (px), 160–500, step 10. */\n  --width: calc(var(--m-sidebar-width, 260) * 1px);\n  --space-color: #6c5ce7;\n  /* Arc's sidebar: warm near-black text, muted space name and icons, a\n     faint dark hover and an opaque light pill for the tab shown. */\n  --fg: #1c1702;\n  --muted: rgba(0, 0, 0, 0.48);\n  --icon: rgba(0, 0, 0, 0.6);\n  --hover: rgba(0, 0, 0, 0.045);\n  --press: rgba(0, 0, 0, 0.08);\n  --active: #ebebeb;\n  --border: rgba(0, 0, 0, 0.1);\n  --drop: #0a84ff;\n  /* Where the page card is: inside the frame (8 px), right of the sidebar\n     when it's docked. */\n  --card-left: var(--width);\n  --card-inset: 8px;\n  --card-radius: 6.25px;\n\n  position: relative;\n  width: 100%;\n  height: 100%;\n  overflow: hidden;\n  color: var(--fg);\n  font: 14px/1.25 -apple-system, BlinkMacSystemFont, \"Segoe UI\", system-ui, sans-serif;\n  user-select: none;\n  -webkit-user-select: none;\n}\n.arcadia *, .arcadia *::before, .arcadia *::after { box-sizing: border-box; }\n.arcadia img { -webkit-user-drag: none; }\n.arcadia input { -webkit-user-select: text; user-select: text; }\n.arcadia button { font: inherit; color: inherit; background: none; border: 0; cursor: pointer; }\n.arcadia a { color: inherit; text-decoration: none; }\n.arcadia ul { list-style: none; margin: 0; padding: 0; }\n.arcadia .spacer { flex: 1; }\n\n/* Hidden: the page in the frame (8 px all round), or, with the frame off,\n   the whole window. */\n.arcadia:is([data-sidebar=\"hidden\"], [data-sidebar=\"peek\"]) { --card-left: 8px; }\n.arcadia:not(.framed):is([data-sidebar=\"hidden\"], [data-sidebar=\"peek\"]) { --card-left: 0px; --card-inset: 0px; --card-radius: 0px; }\n/* The new-tab page: the sidebar always beside the launcher. */\n.arcadia.newtab { --card-left: var(--width); --card-inset: 8px; --card-radius: 6.25px; }\n\n/* ---- The frame and the page card ------------------------------------------- */\n\n/* The page's place. Its spread shadow is the frame around it; the card\n   itself stays clear (the page shows through). */\n.page, .card-edge, .launcher-slot {\n  position: absolute;\n  top: var(--card-inset);\n  right: var(--card-inset);\n  bottom: var(--card-inset);\n  left: var(--card-left);\n  border-radius: var(--card-radius);\n}\n.page { box-shadow: 0 0 0 100vmax var(--frame); }\n.arcadia:not(.framed):is([data-sidebar=\"hidden\"], [data-sidebar=\"peek\"]):not(.newtab) .page { box-shadow: none; }\n/* The card's soft shadow, above the sidebar so it also falls on its edge. */\n.card-edge { pointer-events: none; box-shadow: 0 1px 5px rgba(0, 0, 0, 0.24), 0 0 3px rgba(0, 0, 0, 0.06); }\n.arcadia:not(.framed):is([data-sidebar=\"hidden\"], [data-sidebar=\"peek\"]):not(.newtab) .card-edge { box-shadow: none; }\n/* Out of Keep open, and back, the card's edge travels with the sidebar. */\n.card-edge { transition: left 200ms ease; }\n.arcadia.m-resizing .card-edge { transition: none; }\n@media (prefers-reduced-motion: reduce) { .card-edge { transition: none; } }\n\n/* Page-load indicator (Arc): a small dark pill centered over the page, in\n   the frame's 8 px top strip (at the top of the page with no frame). Fades\n   and widens in, pulses gently while loading, fades out. */\n.loader {\n  position: absolute;\n  top: -6px;\n  left: 50%;\n  width: 48px;\n  height: 4px;\n  transform: translateX(-50%) scaleX(0.85);\n  opacity: 0;\n  visibility: hidden;\n  pointer-events: none;\n  transition: opacity 250ms ease, transform 250ms ease, visibility 0s linear 250ms;\n}\n.arcadia:not(.framed):is([data-sidebar=\"hidden\"], [data-sidebar=\"peek\"]):not(.newtab) .loader { top: 2px; }\n.arcadia.loading .loader { opacity: 1; visibility: visible; transform: translateX(-50%) scaleX(1); transition: opacity 250ms ease, transform 250ms ease; }\n.loader-bar { width: 100%; height: 100%; border-radius: 2px; background: rgba(28, 28, 30, 0.88); box-shadow: 0 0 0 0.5px rgba(255, 255, 255, 0.3); }\n.arcadia.loading .loader-bar { animation: arcadia-pulse 1.2s ease-in-out 250ms infinite; }\n@keyframes arcadia-pulse { 50% { opacity: 0.55; } }\n/* A tab loading, in its row (the tab in front also has the pill): its icon\n   pulses, no hover needed. */\n.margin-sidebar :is(.tab, .pin).busy .avatar { animation: arcadia-pulse 1.2s ease-in-out infinite; }\n/* Margin's trackpad gestures on the page: a round badge over the page card. */\n.gesture { --gesture: 0; position: absolute; display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%; background: rgba(28, 28, 30, 0.88); color: #fff; box-shadow: 0 0 0 0.5px rgba(255, 255, 255, 0.3), 0 2px 8px rgba(0, 0, 0, 0.25); pointer-events: none; opacity: calc(0.3 + var(--gesture) * 0.7); }\n.gesture .line-icon { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }\n.gesture.pull { top: 14px; left: 50%; transform: translate(-50%, calc((var(--gesture) - 1) * 24px)) rotate(calc(var(--gesture) * 270deg)); }\n.gesture.swipe.back { left: 14px; top: 50%; transform: translate(calc((var(--gesture) - 1) * 24px), -50%); }\n.gesture.swipe.forward { right: 14px; top: 50%; transform: translate(calc((1 - var(--gesture)) * 24px), -50%); }\n.gesture.swipe.forward .line-icon { transform: scaleX(-1); }\n.gesture.armed { background: var(--space-color, rgba(28, 28, 30, 0.88)); }\n.gesture.done { opacity: 0; transition: opacity 250ms ease 100ms; }\n@media (prefers-reduced-motion: reduce) {\n  .margin-sidebar :is(.tab, .pin).busy .avatar { animation: none; opacity: 0.6; }\n  .loader { transition: opacity 150ms linear, visibility 0s linear 150ms; }\n  .arcadia.loading .loader { transition: opacity 150ms linear; }\n  .arcadia.loading .loader-bar { animation: none; }\n}\n\n/* ---- The sidebar ----------------------------------------------------------- */\n\n.margin-sidebar {\n  position: absolute;\n  z-index: 0;\n  top: 0;\n  left: 0;\n  width: var(--width);\n  height: 100%;\n  display: flex;\n  flex-direction: column;\n  padding: 0 8px;\n  background: var(--frame);\n  color: var(--fg);\n  -webkit-font-smoothing: antialiased;\n}\n/* Hidden or out over the page: a floating card inset from the edges, which\n   never moves the page. */\n.arcadia:is([data-sidebar=\"hidden\"], [data-sidebar=\"peek\"]):not(.newtab) .margin-sidebar {\n  top: 8px;\n  left: 8px;\n  height: calc(100% - 16px);\n  border-radius: 6.25px; /* the page card's */\n  box-shadow: 0 0 0 1px var(--border), 0 12px 40px rgba(0, 0, 0, 0.22);\n  transform: translateX(calc(-100% - 16px));\n  visibility: hidden;\n  transition: transform 160ms ease, visibility 0s linear 160ms;\n}\n.arcadia[data-sidebar=\"peek\"]:not(.newtab) .margin-sidebar {\n  transform: none;\n  visibility: visible;\n  transition: transform 160ms ease;\n}\n.arcadia.m-resizing .margin-sidebar, .arcadia.m-resizing .margin-sidebar * { transition: none !important; }\n@media (prefers-reduced-motion: reduce) { .margin-sidebar { transition: none !important; } }\n\n/* The hover zone that brings a hidden sidebar out (Margin's m-peek). */\n.peek-zone { display: none; position: absolute; left: 0; top: 0; bottom: 0; width: var(--m-reveal-zone, 10px); }\n.arcadia[data-sidebar=\"hidden\"]:not(.newtab) .peek-zone { display: block; }\n\n/* Arc's icons, one flat gray: drawn black and faded as a whole, so\n   overlapping strokes don't come out darker. */\n.margin-sidebar .line-icon { display: block; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }\n.margin-sidebar .fill-icon { display: block; fill: currentColor; }\n.margin-sidebar :is(.keep-open, .bar-button, .icon, .new-tab-row .plus) { color: #000; }\n.margin-sidebar :is(.keep-open, .bar-button, .icon, .new-tab-row .plus) :is(.line-icon, .fill-icon) { opacity: 0.6; }\n\n/* The top: the sidebar toggle (Keep open / Auto-hide) where Arc has it. */\n.margin-sidebar .top { flex: none; display: flex; align-items: flex-start; height: 43px; padding-top: 8.75px; }\n.margin-sidebar :is(.keep-open, .bar-button) {\n  flex: none;\n  display: grid;\n  place-items: center;\n  width: 30px;\n  height: 28px;\n  border-radius: 7px;\n}\n.margin-sidebar .keep-open { margin-left: 6px; }\n.margin-sidebar .toggle-icon { width: 18.5px; height: 14.5px; }\n.margin-sidebar :is(.keep-open, .bar-button):hover { background: var(--hover); }\n.margin-sidebar :is(.keep-open, .bar-button):active { background: var(--press); }\n.arcadia.newtab .keep-open { display: none; }\n/* Windowed (Margin covers the browser's toolbar): the window's buttons and\n   an address button that opens the command bar. Not in a page or full screen. */\n.window-controls, .margin-sidebar .address { display: none; }\n.arcadia[data-mode=\"windowed\"] .window-controls { display: block; flex: none; width: 60px; height: 14px; margin: 7px 4px 0 6px; }\n.arcadia[data-mode=\"windowed\"] .margin-sidebar .address { display: grid; }\n.margin-sidebar .search-icon { width: 15px; height: 15px; }\n\n/* The space's name (Arc): its emoji and name, muted. */\n.margin-sidebar .space-title {\n  flex: none;\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  height: 36px;\n  margin-bottom: 5px;\n  padding-left: 10.5px;\n  color: var(--muted);\n  font-size: 13px;\n  font-weight: 600;\n}\n.margin-sidebar .space-title .emoji { flex: none; position: relative; top: -1px; width: 17px; margin: 0 -0.5px; font-size: 17px; line-height: 17px; text-align: center; color: initial; }\n\n/* The space's part (name, editor, list), which a sideways swipe drags\n   (Margin's m-swipe). */\n.margin-sidebar .space-pane { flex: 1; min-height: 0; display: flex; flex-direction: column; }\n.margin-sidebar.m-swiping { overflow: clip; }\n.margin-sidebar.m-swiping .space-pane { will-change: transform; transform: translateX(var(--m-swipe-offset, 0px)); }\n.margin-sidebar.m-settling .space-pane { transform: translateX(var(--m-swipe-offset, 0px)); transition: transform 220ms cubic-bezier(0.25, 1, 0.5, 1); }\n@media (prefers-reduced-motion: reduce) { .margin-sidebar.m-settling .space-pane { transition: none; } }\n\n/* One list for the pinned area and the tabs; it scrolls under the top and\n   the bottom bar, never the page; no bounce. */\n.margin-sidebar .tabs-section { flex: 1; min-height: 0; margin: 0 -8px; padding: 0 8px 8px; overflow-y: auto; overscroll-behavior: none; }\n.margin-sidebar :is(.pins, .tabs) { display: flex; flex-direction: column; gap: 5px; }\n.margin-sidebar .pins { position: relative; }\n.margin-sidebar .pins:not(.has) { display: none; }\n.margin-sidebar .divider { height: 1px; margin: 10px 10px; background: var(--border); }\n\n/* Rows (Arc): 36 high, 5 apart, radius 12; favicon 16, 10 before the title. */\n.margin-sidebar :is(.tab, .pin, .new-tab-row, .folder) {\n  position: relative;\n  flex: none;\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  height: 36px;\n  padding: 0 6px 0 10px;\n  border-radius: 12px;\n  cursor: default;\n  outline: none;\n}\n.margin-sidebar :is(.tab, .pin, .new-tab-row, .folder):hover { background: var(--hover); }\n.margin-sidebar :is(.tab, .pin, .new-tab-row, .folder):focus-visible { box-shadow: inset 0 0 0 2px var(--drop); }\n/* A press (Arc, Margin's m-pressed): the row shrinks a little while the\n   button is down, and springs back as it comes up. */\n.margin-sidebar :is(.tab, .pin, .new-tab-row, .folder) { transition: transform 300ms cubic-bezier(0.3, 1.5, 0.5, 1); }\n.margin-sidebar :is(.tab, .pin, .new-tab-row, .folder).m-pressed { transform: scale(0.97); transition: transform 100ms cubic-bezier(0.2, 0, 0.3, 1); }\n@media (prefers-reduced-motion: reduce) {\n  .margin-sidebar :is(.tab, .pin, .new-tab-row, .folder).m-pressed { transform: none; }\n}\n.margin-sidebar :is(.tab, .pin, .new-tab-row).active {\n  background: linear-gradient(#efefef, rgba(239, 239, 239, 0) 2px), var(--active);\n  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.2);\n}\n/* While a new tab is being chosen (⌘T, \"+ New Tab\"): the tab whose page is\n   still on screen under the palette, softly; \"+ New Tab\" fully. */\n.margin-sidebar :is(.tab, .pin, .new-tab-row).behind { background: rgba(255, 255, 255, 0.4); }\n\n/* A folder: its icon, then its name in semibold; its pins indented beneath. */\n.margin-sidebar .folder { padding-left: 8px; font-weight: 600; }\n.margin-sidebar .folder-toggle { flex: 1; min-width: 0; height: 100%; display: flex; align-items: center; gap: 6px; border-radius: 10px; }\n.margin-sidebar .folder-icon { flex: none; position: relative; top: 1px; width: 22.5px; height: 16.5px; overflow: visible; }\n/* Arc's colors: a golden back panel, an off-white front, a dark brown outline. */\n.margin-sidebar .folder-icon .folder-back { fill: #d0a004; stroke: #5f4904; stroke-width: 1.2; stroke-linejoin: round; }\n.margin-sidebar .folder-icon .folder-front { fill: #f2ecd9; stroke: #5f4904; stroke-width: 1.2; stroke-linejoin: round; }\n.margin-sidebar .pin.nested { margin-left: 16px; }\n/* A name edited in place (Margin's m-rename): Arc's field look. */\n.margin-sidebar .m-renaming {\n  flex: 1;\n  min-width: 0;\n  height: 26px;\n  line-height: 26px;\n  margin-right: 2px;\n  padding: 0 6px;\n  border-radius: 6px;\n  background: rgba(255, 255, 255, 0.75);\n  color: var(--fg);\n  outline: 2px solid var(--drop);\n  text-overflow: clip;\n}\n\n/* \"+ New Tab\", the first row of the tab list (Arc). */\n.margin-sidebar .new-tab-row { color: var(--muted); }\n.margin-sidebar .new-tab-row.active { color: var(--fg); }\n.margin-sidebar .new-tab-row .plus { flex: none; display: grid; place-items: center; width: 16px; height: 16px; }\n.margin-sidebar .new-tab-row .plus-icon { width: 12px; height: 12px; stroke-width: 1.75; }\n.margin-sidebar .title { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }\n.arcadia .avatar { flex: none; width: 16px; height: 16px; border-radius: 4px; object-fit: contain; }\n.arcadia .avatar.letter {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  background: var(--letter, #636e72);\n  color: #fff;\n  font-size: 10px;\n  font-weight: 600;\n}\n/* A tab asleep (it gave its memory back): its icon faded. One playing sound:\n   a small speaker. */\n.margin-sidebar :is(.tab, .pin).asleep .avatar { opacity: 0.45; filter: grayscale(1); }\n/* A tab that isn't open (its window closed, Safari didn't restore it, or it\n   was put to sleep): still in its space, dimmed; a click opens it. */\n.margin-sidebar .tab.not-open .avatar { opacity: 0.45; filter: grayscale(1); }\n.margin-sidebar .tab.not-open .title { opacity: 0.55; }\n.margin-sidebar .audible-icon { flex: none; width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.4; stroke-linecap: round; stroke-linejoin: round; opacity: 0.55; }\n.margin-sidebar .audible-icon .speaker { fill: currentColor; stroke: none; }\n.margin-sidebar :is(.tab, .pin):hover .audible-icon { display: none; }\n/* × on a row: shown on hover (Arc). */\n.margin-sidebar .icon {\n  flex: none;\n  display: grid;\n  place-items: center;\n  width: 24px;\n  height: 24px;\n  padding: 0;\n  border-radius: 7px;\n  visibility: hidden;\n}\n.margin-sidebar .icon .close-icon { width: 11px; height: 11px; stroke-width: 1.75; }\n.margin-sidebar :is(.tab, .pin):hover .icon { visibility: visible; }\n.margin-sidebar .icon:hover { background: var(--press); }\n\n/* iCloud Tabs (Margin's <m-cloud-tabs>): the tabs open on the person's other\n   devices, above \"+ New Tab\". It reads as one of Arc's folders (the same\n   row, its icon in the folder's place) but plainly live: a sky-blue cloud\n   instead of the golden folder, a count and a turning chevron, nothing to\n   drag in or out. Under it each device is a quiet heading (its icon, name\n   and when it was last used); its tabs are two lines, the title over the\n   site, so they never pass for this window's own. A device not used for a\n   week is dimmed. */\n.margin-sidebar .cloud { display: flex; flex-direction: column; gap: 2px; }\n.margin-sidebar .cloud-head { padding-right: 10px; }\n.margin-sidebar .cloud-icon { flex: none; position: relative; top: 1px; width: 22.5px; height: 16.5px; overflow: visible; }\n.margin-sidebar .cloud-icon .cloud-back { fill: #cde5ff; stroke: #1d5a96; stroke-width: 1.2; stroke-linejoin: round; }\n.margin-sidebar .cloud-icon .cloud-shine { fill: none; stroke: #fff; stroke-width: 1.4; stroke-linecap: round; }\n.margin-sidebar .cloud-count { flex: none; color: var(--muted); font-size: 12px; font-weight: 500; font-variant-numeric: tabular-nums; }\n.margin-sidebar .cloud-chevron { flex: none; width: 10px; height: 10px; fill: none; stroke: var(--icon); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; transition: transform 160ms ease; }\n.margin-sidebar .cloud-head.open .cloud-chevron { transform: rotate(90deg); }\n.margin-sidebar .cloud-note {\n  display: flex;\n  flex-direction: column;\n  align-items: flex-start;\n  gap: 7px;\n  margin: 2px 4px 4px 16px;\n  padding: 9px 11px;\n  border-radius: 10px;\n  background: rgba(255, 255, 255, 0.45);\n  color: var(--muted);\n  font-size: 12px;\n  line-height: 1.35;\n  user-select: text;\n  -webkit-user-select: text;\n}\n.margin-sidebar .cloud-fix { padding: 4px 10px; border-radius: 7px; background: rgba(0, 0, 0, 0.07); color: var(--fg); font-size: 12px; font-weight: 600; }\n.margin-sidebar .cloud-fix:hover { background: rgba(0, 0, 0, 0.11); }\n.margin-sidebar .cloud-fix:focus-visible { outline: 2px solid var(--drop); outline-offset: 1px; }\n.margin-sidebar .cloud-device {\n  flex: none;\n  display: flex;\n  align-items: center;\n  gap: 7px;\n  height: 26px;\n  margin: 5px 0 0 16px;\n  padding: 0 8px 0 7px;\n  border-radius: 8px;\n  color: var(--muted);\n  font-size: 12px;\n  font-weight: 600;\n  cursor: default;\n  outline: none;\n}\n.margin-sidebar .cloud-device:hover { background: var(--hover); }\n.margin-sidebar .cloud-device:focus-visible { box-shadow: inset 0 0 0 2px var(--drop); }\n.margin-sidebar .device-icon { flex: none; display: grid; place-items: center; width: 16px; height: 16px; }\n.margin-sidebar .device-icon svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.3; stroke-linecap: round; stroke-linejoin: round; }\n/* The name keeps its room; \"updated …\" gives way first. */\n.margin-sidebar .device-name { flex: 0 1 auto; min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }\n.margin-sidebar .device-when { flex: 1 100 auto; min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; text-align: right; font-size: 11px; font-weight: 400; opacity: 0.85; }\n.margin-sidebar .cloud-device:not(.open) .device-icon { opacity: 0.7; }\n.margin-sidebar .cloud-tab {\n  position: relative;\n  flex: none;\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  height: 38px;\n  margin-left: 16px;\n  padding: 0 8px 0 10px;\n  border-radius: 12px;\n  cursor: default;\n  outline: none;\n}\n.margin-sidebar .cloud-tab:hover { background: var(--hover); }\n.margin-sidebar .cloud-tab:active { background: var(--press); }\n.margin-sidebar .cloud-tab:focus-visible { box-shadow: inset 0 0 0 2px var(--drop); }\n.margin-sidebar .cloud-text { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 1px; }\n.margin-sidebar .cloud-text .title { flex: none; font-size: 13px; line-height: 16px; }\n.margin-sidebar .cloud-host { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; color: var(--muted); font-size: 11px; line-height: 13px; }\n.margin-sidebar .pinned-mark { flex: none; display: grid; place-items: center; width: 14px; height: 14px; color: var(--icon); }\n.margin-sidebar .pinned-mark svg { width: 11px; height: 11px; fill: none; stroke: currentColor; stroke-width: 1.2; stroke-linejoin: round; }\n.margin-sidebar :is(.cloud-device, .cloud-tab).stale { opacity: 0.5; }\n.margin-sidebar .cloud-divider { margin-top: 8px; }\n@media (prefers-reduced-motion: reduce) {\n  .margin-sidebar .cloud-chevron { transition: none; }\n}\n\n/* Drag and drop (Arc, Margin's m-drag and m-drop): a copy of the row\n   follows the pointer (the row stays), and glides into its new place once\n   dropped. Where it goes: a line in the space's color, a ring at its start,\n   between the rows (2 px, an 8 px ring 8 px in from the row's edge, out to\n   the sidebar's edge); a folder it goes into; the tabs while a pin dropped\n   there unpins. An empty pinned area shows where a tab can go. */\n.m-drag-ghost.tab, .m-drag-ghost.pin, .m-drag-ghost.folder {\n  opacity: 0.9;\n  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.16), 0 1px 2px rgba(0, 0, 0, 0.12);\n  transition: none;\n  will-change: transform;\n}\n.m-drag-ghost:not(.active) { background: rgba(255, 255, 255, 0.6); }\n.m-drag-ghost .icon { visibility: hidden; }\n.margin-sidebar .m-landing { visibility: hidden; }\n.arcadia.m-dragging .margin-sidebar :is(.tab, .pin, .folder, .new-tab-row):hover:not(.active) { background: none; }\n.margin-sidebar .m-drop-before::before, .margin-sidebar .m-drop-after::after, .margin-sidebar .pins.m-drop-end::after {\n  content: \"\";\n  position: absolute;\n  z-index: 1;\n  left: 8px;\n  right: -8px;\n  height: 8px;\n  background:\n    radial-gradient(circle at 4px 50%, transparent 2px, var(--space-color) 2.4px, var(--space-color) 3.6px, transparent 4px) no-repeat 0 0 / 8px 8px,\n    linear-gradient(var(--space-color), var(--space-color)) no-repeat 7.5px 50% / calc(100% - 7.5px) 2px;\n  pointer-events: none;\n}\n.margin-sidebar .m-drop-before::before { top: -6.5px; }\n.margin-sidebar .pins > .m-drop-before:first-child::before { top: -2px; } /* the list's top edge would clip it */\n.margin-sidebar .m-drop-after::after { bottom: -6.5px; }\n.margin-sidebar .pins.m-drop-end::after { bottom: -6.5px; }\n.margin-sidebar .folder.m-drop-into { background: rgba(10, 132, 255, 0.16); box-shadow: inset 0 0 0 2px rgba(10, 132, 255, 0.6); }\n.margin-sidebar .tabs.m-drop-into { border-radius: 12px; box-shadow: 0 0 0 2px rgba(10, 132, 255, 0.45); }\n.margin-sidebar .chip.m-drop-into { outline: 2px dashed var(--chip-color); }\n.margin-sidebar .drop-hint { display: none; }\n.arcadia.m-drag-tab .margin-sidebar .pins:not(.has) {\n  display: block;\n  height: 36px;\n  border: 1.5px dashed rgba(0, 0, 0, 0.25);\n  border-radius: 12px;\n}\n.arcadia.m-drag-tab .margin-sidebar .pins:not(.has) .drop-hint { display: block; line-height: 33px; text-align: center; color: var(--muted); font-size: 13px; }\n\n/* The bottom bar (Arc): archive at the left, the spaces in the middle (the\n   current one in color, the others faded to gray), \"+\" at the right. */\n.margin-sidebar .bar {\n  flex: none;\n  display: grid;\n  grid-template-columns: 1fr auto 1fr;\n  column-gap: 4px;\n  align-items: center;\n  height: 51px; /* 50 under the 1px line */\n  margin: 0 -8px;\n  padding: 0 9px;\n  border-top: 1px solid rgba(0, 0, 0, 0.05);\n}\n.margin-sidebar .bar .archive { justify-self: start; }\n.margin-sidebar .bar .add { justify-self: end; }\n.margin-sidebar .bar .archive-icon { width: 14px; height: 16.5px; }\n.margin-sidebar .bar .plus-icon { width: 14px; height: 14px; stroke-width: 1.75; }\n.margin-sidebar .spaces { display: flex; align-items: center; gap: 4px; min-width: 0; overflow-x: auto; scrollbar-width: none; }\n/* An emoji's ink sits at the start of its advance: nudged to look centered. */\n.margin-sidebar .chip {\n  flex: none;\n  position: relative;\n  top: -1px;\n  width: 30px;\n  height: 28px;\n  padding: 0 0 0 4px;\n  border-radius: 7px;\n  font-size: 15px;\n  line-height: 28px;\n  filter: grayscale(1);\n  opacity: 0.55;\n}\n.margin-sidebar .chip:hover { opacity: 0.85; background: var(--hover); }\n.margin-sidebar .chip.active { filter: none; opacity: 1; }\n/* Another browser profile's space: its profile's mark at the corner; a divider between profiles. */\n.margin-sidebar .chip .profile-mark {\n  position: absolute;\n  right: 1px;\n  bottom: 2px;\n  min-width: 11px;\n  height: 11px;\n  padding: 0 2px;\n  border-radius: 6px;\n  background: var(--profile-color, #636e72);\n  color: #fff;\n  font: 700 7.5px/11px -apple-system, system-ui, sans-serif;\n  text-align: center;\n  filter: none;\n}\n.margin-sidebar .chip.switching { opacity: 0.85; animation: margin-chip-switching 0.9s ease-in-out infinite alternate; }\n@keyframes margin-chip-switching { to { opacity: 0.4; } }\n.margin-sidebar .profile-divider { flex: none; width: 1px; height: 16px; margin: 0 2px; background: currentColor; opacity: 0.2; }\n\n/* The space editor (Margin's <m-editor>, the \"space-editor\" part), under the space's name. */\n.margin-sidebar .editor {\n  flex: none;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  margin: 0 2px 8px;\n  padding: 8px;\n  border-radius: 10px;\n  background: rgba(255, 255, 255, 0.2);\n  font-size: 13px;\n}\n.margin-sidebar .editor .row { display: flex; gap: 6px; align-items: center; }\n.margin-sidebar .editor input {\n  min-width: 0;\n  height: 28px;\n  padding: 0 8px;\n  border: 1px solid var(--border);\n  border-radius: 7px;\n  background: rgba(255, 255, 255, 0.55);\n  color: var(--fg);\n  font: inherit;\n  outline: none;\n}\n.margin-sidebar .editor input:focus { border-color: var(--space-color); }\n.margin-sidebar .editor .emoji { width: 40px; flex: none; text-align: center; font-size: 15px; }\n.margin-sidebar .editor .name { flex: 1; }\n.margin-sidebar .editor .name:disabled { opacity: 0.7; }\n.margin-sidebar .editor .note { color: var(--muted); font-size: 11px; line-height: 1.35; }\n.margin-sidebar .chip .profile-mark .profile-symbol { display: block; width: 8px; height: 8px; margin: 1.5px auto 0; }\n.margin-sidebar .swatches { display: flex; gap: 6px; flex-wrap: wrap; }\n.margin-sidebar .swatch { width: 20px; height: 20px; padding: 0; border-radius: 50%; background: var(--chip-color); }\n.margin-sidebar .swatch[aria-checked=\"true\"] { box-shadow: 0 0 0 2px var(--frame), 0 0 0 4px var(--chip-color); }\n.margin-sidebar .editor .actions button { height: 26px; padding: 0 10px; border-radius: 7px; color: var(--muted); }\n.margin-sidebar .editor .actions button:hover { background: var(--hover); color: var(--fg); }\n.margin-sidebar .editor .actions .primary { background: var(--space-color); color: #fff; }\n.margin-sidebar .editor .actions .delete, .margin-sidebar .editor .actions .delete:hover { color: #d63031; }\n.margin-sidebar .editor .delete:disabled { opacity: 0.4; cursor: default; }\n\n/* Resize handle (Arc): on hover or while dragging, a soft light pill runs\n   the height of the page card, just inside the sidebar's edge, 2 px from\n   the page. The hit area (12 px) straddles the edge. */\n.resizer {\n  position: absolute;\n  top: 0;\n  right: -4px;\n  width: 12px;\n  height: 100%;\n  cursor: col-resize;\n  z-index: 2;\n  touch-action: none;\n}\n.resizer::after {\n  content: \"\";\n  position: absolute;\n  top: 8px;\n  bottom: 8px;\n  right: 6px;\n  width: 4px;\n  border-radius: 2px;\n  background: rgba(255, 255, 255, 0.6);\n  opacity: 0;\n  transition: opacity 120ms ease;\n}\n.resizer:hover::after, .resizer.m-resizing::after { opacity: 1; }\n.arcadia.m-resizing { cursor: col-resize; }\n.arcadia:is([data-sidebar=\"hidden\"], [data-sidebar=\"peek\"]):not(.newtab) .resizer { display: none; }\n\n/* ---- Right-click menus (Margin's <m-menu>, the \"menu\" part) ----------------- */\n\n.tab-menu {\n  min-width: 180px;\n  max-width: calc(100vw - 8px);\n  /* Many folders, many items: it scrolls, its last ones stay reachable. */\n  max-height: calc(100vh - 8px);\n  overflow-x: hidden;\n  overflow-y: auto;\n  overscroll-behavior: contain;\n  padding: 5px;\n  border-radius: 8px;\n  background: rgba(246, 246, 246, 0.97);\n  box-shadow: 0 0 0 0.5px rgba(0, 0, 0, 0.18), 0 8px 24px rgba(0, 0, 0, 0.22);\n  -webkit-backdrop-filter: blur(20px);\n  backdrop-filter: blur(20px);\n  color: #1c1c1e;\n  -webkit-font-smoothing: antialiased;\n}\n.menu-slot:focus { outline: none; }\n.tab-menu .menu-item {\n  display: block;\n  width: 100%;\n  height: 24px;\n  padding: 0 10px;\n  border-radius: 5px;\n  overflow: hidden;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n  text-align: left;\n  font-size: 13px;\n  font-weight: 400;\n  outline: none;\n  cursor: default;\n}\n.tab-menu .menu-item:focus { background: #0a84ff; color: #fff; }\n.menu-separator { height: 1px; margin: 5px 10px; background: rgba(0, 0, 0, 0.12); }\n\n/* ---- Notices and prompts (Margin's <m-notice> and <m-prompt>) --------------- */\n\n/* A notice near the left edge (e.g. \"Margin works in full screen\"), above\n   the page, never in the way for long. */\n.notice {\n  position: absolute; top: 12px; left: 12px; z-index: 3;\n  display: flex; align-items: center; gap: 8px; max-width: min(420px, calc(100% - 24px));\n  /* As wide as its words, up to the cap (it's placed in a box of no size, so min-content went a word per line). */\n  width: max-content;\n  padding: 8px 8px 8px 12px; border-radius: 10px;\n  background: rgba(28, 28, 30, 0.92); color: #fff; font: 13px/1.3 -apple-system, BlinkMacSystemFont, \"Helvetica Neue\", sans-serif;\n  box-shadow: 0 6px 24px rgba(0, 0, 0, 0.25); pointer-events: auto;\n}\n.notice .text { flex: 1; }\n.notice button { height: 26px; padding: 0 10px; border-radius: 7px; color: #fff; background: rgba(255, 255, 255, 0.12); white-space: nowrap; }\n.notice button:hover { background: rgba(255, 255, 255, 0.2); }\n.notice button.primary { background: #6c5ce7; }\n.notice button.primary:hover { background: #7d6ff0; }\n\n/* A prompt: the notice's dark card, centered, a question and its buttons. */\n.prompt-layer { position: absolute; inset: 0; z-index: 4; display: grid; place-items: center; background: rgba(0, 0, 0, 0.12); }\n.prompt {\n  width: min(380px, calc(100% - 32px));\n  display: flex; flex-direction: column; gap: 8px;\n  padding: 16px; border-radius: 12px;\n  background: rgba(28, 28, 30, 0.94); color: #fff; font: 13px/1.35 -apple-system, BlinkMacSystemFont, \"Helvetica Neue\", sans-serif;\n  box-shadow: 0 0 0 0.5px rgba(255, 255, 255, 0.2), 0 18px 50px rgba(0, 0, 0, 0.4);\n  -webkit-font-smoothing: antialiased;\n}\n.prompt-title { font-size: 14px; font-weight: 600; }\n.prompt-text { color: rgba(255, 255, 255, 0.75); }\n.prompt-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 6px; }\n.prompt button { height: 28px; padding: 0 12px; border-radius: 7px; color: #fff; background: rgba(255, 255, 255, 0.12); white-space: nowrap; }\n.prompt button:hover { background: rgba(255, 255, 255, 0.2); }\n.prompt button.primary { background: #6c5ce7; }\n.prompt button.danger { background: #d63031; }\n\n/* ---- The command bar (Arc) ------------------------------------------------- */\n\n/* A dark, translucent panel centered on the window, a third of the way\n   down; one-line rows with the space name and an arrow button; the\n   selected row takes the current space's color. Measured from Arc: 765\n   wide, five rows tall, the top 306 below the window's top in a 949-high\n   window. English and laid out as Arc's, right-to-left too. */\n.palette-layer { position: absolute; inset: 0; z-index: 5; }\n/* Catches clicks outside; Arc doesn't dim the page. */\n.palette-layer .backdrop { position: absolute; inset: 0; width: 100%; height: 100%; padding: 0; background: transparent; cursor: default; }\n.palette {\n  --fg: #f2f1f4;\n  --muted: rgba(242, 241, 244, 0.55);\n  --row-hover: rgba(255, 255, 255, 0.06);\n  --border: rgba(255, 255, 255, 0.1);\n  --rows: 5;\n\n  position: absolute;\n  top: 32.25%;\n  left: 50%;\n  transform: translateX(-50%);\n  width: min(765px, calc(100% - 32px));\n  /* Five rows, as Arc (border, search, list padding, rows and the gaps\n     between them); more scroll, the selection followed. */\n  max-height: calc(2px + 63px + 6px + var(--rows) * 46px + (var(--rows) - 1) * 4px + 10.4px);\n  direction: ltr;\n  display: flex;\n  flex-direction: column;\n  background: rgba(36, 32, 36, 0.86);\n  backdrop-filter: blur(28px) saturate(1.5);\n  -webkit-backdrop-filter: blur(28px) saturate(1.5);\n  color: var(--fg);\n  border: 1px solid var(--border);\n  border-radius: 12px;\n  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.45), 0 0 0 0.5px rgba(0, 0, 0, 0.4);\n  overflow: hidden;\n  font: 13px/1.3 -apple-system, BlinkMacSystemFont, \"Segoe UI\", system-ui, sans-serif;\n  -webkit-font-smoothing: antialiased;\n  user-select: none;\n}\n/* Short windows: higher up, then fewer whole rows (never half of one). */\n@media (max-height: 507px) { .palette { top: 18%; } }\n@media (max-height: 418px) { .palette { --rows: 4; } }\n@media (max-height: 357px) { .palette { --rows: 3; } }\n\n/* 62 high above a divider inset from the sides; the magnifier centered on\n   the row icons' column, the text where the titles start. */\n.palette .search {\n  position: relative;\n  flex: none;\n  display: flex;\n  align-items: center;\n  gap: 11.5px;\n  height: 63px;\n  padding: 0 0 2.5px 22.5px; /* content a little above center, as Arc */\n}\n.palette .search::after {\n  content: \"\";\n  position: absolute;\n  left: 10.7px;\n  right: 10.7px;\n  bottom: 0;\n  height: 1px;\n  background: var(--border);\n}\n.palette .search-icon { flex: none; width: 16px; height: 16px; fill: none; stroke: var(--muted); stroke-width: 2; stroke-linecap: round; }\n.palette .query {\n  flex: 1;\n  min-width: 0;\n  height: 100%;\n  padding: 0;\n  border: 0;\n  background: transparent;\n  color: var(--fg);\n  font: inherit;\n  font-size: 18.5px;\n  outline: none;\n}\n.palette .query::placeholder { color: var(--muted); }\n.palette .results {\n  margin: 0;\n  padding: 6px 8.5px 10.4px;\n  overflow-y: auto;\n  overscroll-behavior: none;\n  scrollbar-width: none;\n  scroll-padding: 6px 0 10.4px; /* the selection scrolled into view keeps the padding */\n}\n.palette .result {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  height: 46px;\n  padding: 0 13px 0 10px;\n  border-radius: 6px;\n  cursor: default;\n}\n.palette .result + .result { margin-top: 4px; }\n/* The heading of a run of rows from one place (iCloud Tabs: \"On Tirth's iPhone\"). */\n.palette .result-section { padding: 12px 10px 5px; color: var(--muted); font-size: 12px; font-weight: 600; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }\n.palette .result:hover { background: var(--row-hover); }\n.palette .result[aria-selected=\"true\"] { background: color-mix(in srgb, var(--space-color) 82%, #000); }\n.palette .result.empty { color: var(--muted); justify-content: center; }\n/* Each icon fills a 24 px slot: favicons 14 px in it (on a white tile when\n   selected, as Arc), letters on a 16 px tile, emoji at 15 px. */\n.palette .avatar { width: 24px; height: 24px; }\n.palette img.avatar { box-sizing: content-box; width: 14px; height: 14px; padding: 5px; }\n.palette [aria-selected=\"true\"] img.avatar { background: #fff; }\n.palette .avatar.letter { width: 16px; height: 16px; margin: 0 4px; }\n.palette .avatar.emoji { display: inline-flex; align-items: center; justify-content: center; font-size: 15px; }\n.palette .title { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; font-weight: 500; }\n.palette .badge { flex: none; margin-right: 0.5px; color: var(--muted); font-weight: 500; }\n.palette [aria-selected=\"true\"] .badge { color: rgba(255, 255, 255, 0.92); }\n.palette .go-button {\n  flex: none;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 24px;\n  height: 24px;\n  border-radius: 4px;\n  background: rgba(255, 255, 255, 0.1);\n}\n.palette .arrow-icon { width: 18px; height: 18px; fill: none; stroke: var(--fg); stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }\n.palette [aria-selected=\"true\"] .go-button { background: #f2f0e8; }\n.palette [aria-selected=\"true\"] .arrow-icon { stroke: #1c1c1e; }\n\n/* ---- Switching to another profile (Margin's <m-switch-cover>) -------------- */\n\n/* Over the page card while Margin.app gets the other profile's window ready:\n   the frame's gray, lighter, and where it goes, centred. Under the sidebar\n   (earlier in the template), so one out over the page stays in front; the\n   launcher steps aside. No fade: it comes and goes with the switch. */\n.switch-cover-slot {\n  position: absolute;\n  top: var(--card-inset);\n  right: var(--card-inset);\n  bottom: var(--card-inset);\n  left: var(--card-left);\n  border-radius: var(--card-radius);\n  overflow: hidden;\n}\n.arcadia.switching .launcher-slot { visibility: hidden; }\n.switch-cover { position: absolute; inset: 0; display: grid; place-items: center; background: #c9cacd; pointer-events: auto; }\n.switch-cover-card { display: flex; flex-direction: column; align-items: center; gap: 8px; max-width: 80%; color: var(--fg); text-align: center; -webkit-font-smoothing: antialiased; }\n.switch-cover-mark { width: 40px; height: 40px; border-radius: 11px; display: grid; place-items: center; background: var(--profile, var(--space-color)); color: #fff; font-size: 18px; font-weight: 700; }\n.switch-cover-mark.emoji { background: rgba(255, 255, 255, 0.6); font-size: 24px; }\n.switch-cover-text { font-size: 15px; font-weight: 600; }\n.switch-cover-space { font-size: 13px; color: var(--muted); }\n\n/* ---- The new-tab launcher (Margin's <m-launcher>, the \"launcher\" part) ------- */\n\n/* In the page card, beside the sidebar: the search field, the space's pins\n   as tiles, recently archived tabs, and Settings. Light or dark, as the\n   system is. */\n.launcher-slot {\n  --bg: #f6f5fa;\n  --fg: #1d1b26;\n  --muted: #6e6a7c;\n  --card: #ffffff;\n  --border: rgba(0, 0, 0, 0.08);\n  --accent: #6c5ce7;\n  overflow: hidden;\n  font: 14px/1.4 -apple-system, BlinkMacSystemFont, \"Segoe UI\", system-ui, sans-serif;\n  color: var(--fg);\n  user-select: text;\n  -webkit-user-select: text;\n}\n@media (prefers-color-scheme: dark) {\n  .launcher-slot { --bg: #18171d; --fg: #ecebf2; --muted: #9a97a8; --card: #24232b; --border: rgba(255, 255, 255, 0.08); }\n}\n.launcher {\n  height: 100%;\n  overflow-y: auto;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 28px;\n  padding: 18vh 32px 48px;\n  background: var(--bg);\n}\n.launcher > * { width: min(640px, 100%); flex: none; }\n.launcher .launcher-query {\n  width: 100%;\n  height: 52px;\n  padding: 0 20px;\n  border: 1px solid var(--border);\n  border-radius: 14px;\n  background: var(--card);\n  color: var(--fg);\n  font: inherit;\n  font-size: 17px;\n  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.06);\n  outline: none;\n}\n.launcher .launcher-query:focus { border-color: var(--accent); }\n.launcher h2 { margin: 0 0 10px; font-size: 12px; font-weight: 600; letter-spacing: 0.04em; text-transform: uppercase; color: var(--muted); }\n.launcher .pin-tiles { display: grid; grid-template-columns: repeat(auto-fill, minmax(104px, 1fr)); gap: 12px; }\n.launcher .tile {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 8px;\n  padding: 16px 8px 12px;\n  border-radius: 14px;\n  background: var(--card);\n  border: 1px solid var(--border);\n  cursor: pointer;\n}\n.launcher .tile:hover { border-color: var(--accent); }\n.launcher .tile .avatar { width: 32px; height: 32px; border-radius: 8px; }\n.launcher .tile .avatar.letter { font-size: 16px; }\n.launcher .tile .title { width: 100%; text-align: center; font-size: 12px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }\n.launcher .archive-row {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 8px 10px;\n  border-radius: 10px;\n  cursor: pointer;\n}\n.launcher .archive-row:hover { background: var(--card); }\n.launcher .archive-row .title { flex: 1; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }\n.launcher .archive-row .when { color: var(--muted); font-size: 12px; }\n.launcher .archive-more { margin-top: 6px; padding: 4px 10px; border-radius: 8px; color: var(--muted); font-size: 13px; }\n.launcher .archive-more:hover { background: var(--card); color: var(--fg); }\n.launcher .settings { color: var(--muted); font-size: 13px; }\n.launcher .settings-summary { display: list-item; list-style: disclosure-closed inside; }\n.launcher .settings-summary button { padding: 0; font-size: 13px; color: var(--muted); }\n.launcher .settings.open .settings-summary { list-style-type: disclosure-open; }\n/* The Settings form (Margin's `settings` part): newtab.css's #settings. */\n.settings-form label.setting { display: flex; justify-content: space-between; align-items: center; gap: 12px; margin-top: 10px; }\n.settings-form label.setting.stacked { flex-direction: column; align-items: stretch; gap: 6px; }\n.settings-form label.setting.disabled { opacity: 0.55; }\n.settings-form :is(select, input, textarea) { font: inherit; color: var(--fg); background: var(--card); border: 1px solid var(--border); border-radius: 8px; padding: 4px 8px; }\n.settings-form input.number { width: 6em; flex: none; }\n.settings-form input.color { flex: none; width: 44px; height: 26px; padding: 2px; border-radius: 6px; cursor: pointer; }\n.settings-form input.toggle { flex: none; width: auto; padding: 0; margin: 0; accent-color: var(--accent); }\n.settings-form input.shortcut { width: 9em; flex: none; cursor: pointer; }\n.settings-form input.shortcut.recording { border-color: var(--accent); }\n.settings-form textarea { resize: vertical; -webkit-user-select: text; user-select: text; }\n.settings-form .help { margin: 6px 0 0; font-size: 12px; }\n.settings-form .help.error { color: #d70015; }\n.settings-form .setting-group { margin-top: 18px; }\n.settings-form .actions { display: flex; align-items: center; gap: 8px; margin-top: 10px; }\n.settings-form .actions button { flex: none; white-space: nowrap; font: inherit; color: var(--muted); background: none; border: 1px solid var(--border); border-radius: 8px; padding: 3px 10px; cursor: pointer; }\n.settings-form .actions .help { margin: 0; }\n\n@media print { .page, .card-edge { box-shadow: none !important; } }\n","files":{}};
